async def run_deferred_startup_maintenance():
    await asyncio.sleep(STARTUP_MAINTENANCE_DELAY_SECONDS)
    STARTUP_MAINTENANCE_STATE.update({
        "status": "running",
        "current": "",
        "started_at": time.time(),
        "finished_at": 0.0,
        "steps": {},
    })
    steps = (
        ("provider_preset_cleanup", run_deferred_provider_preset_cleanup),
        ("local_vision_secret_seed", run_deferred_local_vision_secret_seed),
        ("orphan_output_cleanup", run_deferred_orphan_output_cleanup),
        ("disposable_storage", MAINTENANCE.run_once),
        ("asset_library_migration", migrate_asset_library_into_dirs),
        ("double_extension_migration", migrate_double_extension_uploads),
        ("image_extension_migration", migrate_mislabeled_image_extensions),
        ("work_index", lambda: DATABASE.ensure_work_items_indexed(work_metadata())),
        ("local_upload_index", ensure_local_upload_indexed),
        ("video_clip_reconciliation", lambda: reconcile_video_clip_assets(
            os.fspath(OUTPUT_OUTPUT_DIR),
            DATABASE.list_canvases(include_deleted=None),
        )),
    )
    failed = False
    try:
        for name, operation in steps:
            # 用户刚进入画布时让出启动维护的磁盘/SQLite 竞争窗口；超过短暂 grace 后再继续，
            # 避免维护任务无限期阻塞服务，同时覆盖首屏进入的 p95。
            while ACTIVE_CANVAS_ID and time.time() - ACTIVE_CANVAS_LAST_SEEN < STARTUP_CANVAS_GRACE_SECONDS:
                await asyncio.sleep(0.5)
            STARTUP_MAINTENANCE_STATE["current"] = name
            started = time.perf_counter()
            try:
                result = await asyncio.to_thread(operation)
                STARTUP_MAINTENANCE_STATE["steps"][name] = {
                    "status": "ok",
                    "elapsed_ms": round((time.perf_counter() - started) * 1000),
                    "changed": int(result or 0) if isinstance(result, (int, bool)) else 0,
                }
            except Exception as exc:
                failed = True
                STARTUP_MAINTENANCE_STATE["steps"][name] = {
                    "status": "error",
                    "elapsed_ms": round((time.perf_counter() - started) * 1000),
                    "error": str(exc)[:500],
                }
                print(f"启动后台维护失败 [{name}]: {exc}")
    except asyncio.CancelledError:
        STARTUP_MAINTENANCE_STATE["status"] = "cancelled"
        raise
    finally:
        STARTUP_MAINTENANCE_STATE["current"] = ""
        STARTUP_MAINTENANCE_STATE["finished_at"] = time.time()
        if STARTUP_MAINTENANCE_STATE.get("status") != "cancelled":
            STARTUP_MAINTENANCE_STATE["status"] = "complete_with_errors" if failed else "complete"

async def run_deferred_task_recovery():
    """Restore persisted task state after the health endpoint is available."""
    # 给桌面宿主和首个页面留出时间完成账号、偏好和能力接口请求，
    # 避免历史任务恢复在冷启动瞬间争用线程池和 SQLite。
    await asyncio.sleep(STARTUP_RECOVERY_DELAY_SECONDS)
    operations = (
        ("在线生图任务", load_online_image_tasks_from_disk),
        ("电商专用任务", load_ecommerce_tasks_from_disk),
        ("画布视频任务", load_canvas_video_tasks_from_disk),
    )
    try:
        for label, operation in operations:
            try:
                while ACTIVE_CANVAS_ID and time.time() - ACTIVE_CANVAS_LAST_SEEN < STARTUP_CANVAS_GRACE_SECONDS:
                    await asyncio.sleep(0.5)
                await asyncio.to_thread(operation)
                if operation is load_canvas_video_tasks_from_disk:
                    resume_canvas_video_tasks()
                await asyncio.sleep(0)
            except Exception as exc:  # noqa: BLE001 - recovery must not block service readiness
                print(f"{label}恢复失败: {exc}")
    except asyncio.CancelledError:
        raise


async def startup_event():
    global GLOBAL_LOOP, STARTUP_MAINTENANCE_TASK, STARTUP_RECOVERY_TASK
    GLOBAL_LOOP = asyncio.get_running_loop()
    if DWPOSE_AUTO_DOWNLOAD_ENABLED:
        DWPOSE_MODEL_MANAGER.start_background()
    if DEPTH_AUTO_DOWNLOAD_ENABLED:
        DEPTH_MODEL_MANAGER.start_background()
    # 供应商清理、密钥初始化和遗留占位修复都不是服务就绪的必要条件，
    # 与文件扫描一起延后到健康检查之后，避免桌面宿主等待这些磁盘操作。
    # 历史任务恢复可能读取大量持久化记录，同样不阻塞 /api/health 和首屏窗口。
    STARTUP_RECOVERY_TASK = asyncio.create_task(run_deferred_task_recovery())
    # 文件遍历、历史素材修复和索引补偿同样不阻塞 /api/health；服务就绪后在后台顺序执行。
    STARTUP_MAINTENANCE_TASK = asyncio.create_task(run_deferred_startup_maintenance())


async def shutdown_startup_maintenance():
    global STARTUP_MAINTENANCE_TASK, STARTUP_RECOVERY_TASK
    recovery_task = STARTUP_RECOVERY_TASK
    STARTUP_RECOVERY_TASK = None
    if recovery_task and not recovery_task.done():
        recovery_task.cancel()
        try:
            await recovery_task
        except asyncio.CancelledError:
            pass
    task = STARTUP_MAINTENANCE_TASK
    STARTUP_MAINTENANCE_TASK = None
    if task and not task.done():
        task.cancel()
        try:
            await task
        except asyncio.CancelledError:
            pass


@asynccontextmanager
async def app_lifespan(_app: FastAPI):
    await startup_event()
    try:
        yield
    finally:
        await shutdown_startup_maintenance()


app.router.lifespan_context = app_lifespan

@app.websocket("/ws/events")
@app.websocket("/ws/stats")
async def websocket_endpoint(websocket: WebSocket, client_id: str = None):
    await websocket.accept()
    connected = False
    context_token = None
    try:
        session_token = str(websocket.cookies.get(ACCOUNT_SESSION_COOKIE, "") or "")
        identity = ACCOUNT_STORE.resolve_session(session_token)
        remote_address = str(websocket.client.host if websocket.client else "")
        if identity and identity.is_admin and not is_loopback_address(remote_address):
            identity = None
        if not identity:
            await websocket.close(code=4401, reason="请先登录")
            return
        context_token = set_current_account(identity.account_id)
        client_id = str(client_id or "").strip()
        await manager.connect(websocket, identity.account_id, client_id, accept=False)
        connected = True
        await websocket.send_text(json.dumps({"type": "connection.ready", "account": identity.public()}))
        while True:
            data = await websocket.receive_text()
            if data == "ping" or data == '{"type":"ping"}':
                await websocket.send_text(json.dumps({"type": "pong"}))
    except WebSocketDisconnect:
        if connected:
            await manager.disconnect(websocket, client_id)
    except Exception as e:
        print(f"WS Error: {e}")
        if connected:
            await manager.disconnect(websocket, client_id)
    finally:
        if context_token is not None:
            reset_current_account(context_token)

