@app.get("/api/download-output")
def download_output(request: Request, url: str, name: str = "", inline: bool = False):
    path = output_file_from_url(url)
    if not path:
        path = local_media_file_by_basename(filename_from_media_url(url, ""))
    if path:
        filename = sanitize_export_filename(os.path.basename(name) if name else os.path.basename(path), os.path.basename(path))
        return FileResponse(path, media_type=content_type_for_path(path), filename=None if inline else filename)
    # 远程文件：流式代理，绝不把整段视频/大文件读进内存（否则多个视频同时代理会撑爆内存、拖垮单进程服务）。
    parsed = urllib.parse.urlparse(str(url or "").strip())
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        raise HTTPException(status_code=400, detail="无效的下载地址")
    try:
        upstream_headers = {"User-Agent": "Canvas/1.0"}
        range_header = request.headers.get("range")
        if range_header:
            upstream_headers["Range"] = range_header
        upstream = requests.get(
            url, stream=True, timeout=(10, 60),
            headers=upstream_headers,
        )
        upstream.raise_for_status()
    except requests.RequestException as exc:
        raise HTTPException(status_code=502, detail=f"远程文件下载失败：{exc}")
    content_type = upstream.headers.get("content-type") or "application/octet-stream"
    fallback = filename_from_media_url(url, "download.bin")
    filename = sanitize_export_filename(os.path.basename(name) if name else fallback, fallback)
    disposition = "inline" if inline else "attachment"
    headers = {"Content-Disposition": f"{disposition}; filename*=UTF-8''{urllib.parse.quote(filename)}"}
    content_length = upstream.headers.get("content-length")
    if content_length:
        headers["Content-Length"] = content_length
    for key in ("content-range", "accept-ranges"):
        value = upstream.headers.get(key)
        if value:
            headers["-".join(part.capitalize() for part in key.split("-"))] = value

    def stream_remote():
        try:
            for chunk in upstream.iter_content(chunk_size=256 * 1024):
                if chunk:
                    yield chunk
        finally:
            upstream.close()

    return StreamingResponse(stream_remote(), media_type=content_type, headers=headers, status_code=upstream.status_code)


@app.post("/api/ai/upload")
async def upload_ai_reference(files: List[UploadFile] = File(...)):
    uploaded = []
    image_exts = {".png", ".jpg", ".jpeg", ".webp", ".gif"}
    video_exts = {".mp4", ".webm", ".mov", ".m4v", ".flv"}
    audio_exts = {".mp3", ".wav", ".m4a", ".aac", ".ogg", ".flac"}
    doc_exts = {".pdf", ".txt", ".md", ".markdown", ".doc", ".docx", ".xls", ".xlsx", ".csv", ".json", ".zip", ".yaml", ".yml", ".log"}
    max_upload_bytes = 50 * 1024 * 1024
    for file in files:
        content = await file.read()
        if not content:
            continue
        if len(content) > max_upload_bytes:
            raise HTTPException(status_code=413, detail=f"{file.filename or '文件'} 超过 50MB，无法上传")
        ext = os.path.splitext(file.filename or "")[1].lower()
        content_type = (file.content_type or "").lower()
        kind = "image"
        if ext in video_exts or content_type.startswith("video/"):
            kind = "video"
            if ext not in video_exts:
                ext = ".webm" if "webm" in content_type else ".mov" if "quicktime" in content_type else ".mp4"
        elif ext in audio_exts or content_type.startswith("audio/"):
            kind = "audio"
            if ext not in audio_exts:
                ext = ".wav" if "wav" in content_type else ".ogg" if "ogg" in content_type else ".m4a" if "mp4" in content_type else ".mp3"
        elif ext in image_exts or content_type.startswith("image/"):
            kind = "image"
            if ext not in image_exts:
                ext = ".jpg" if "jpeg" in content_type else ".webp" if "webp" in content_type else ".gif" if "gif" in content_type else ".png"
        elif ext in doc_exts or content_type.startswith(("text/", "application/")):
            kind = "file"
            if not ext:
                ext = mimetypes.guess_extension(content_type) or ".bin"
        else:
            kind = "file"
            if not ext:
                ext = ".bin"
        image_width = 0
        image_height = 0
        orientation_normalized = False
        if kind == "image":
            try:
                content, image_width, image_height, orientation_normalized = normalize_image_orientation(content)
            except ValueError as exc:
                raise HTTPException(status_code=400, detail=f"{file.filename or '图片'} 无法读取：{exc}") from exc
            if len(content) > max_upload_bytes:
                raise HTTPException(status_code=413, detail=f"{file.filename or '图片'} 方向校正后超过 50MB，无法上传")
        filename = f"ai_ref_{uuid.uuid4().hex[:12]}{ext}"
        path = output_path_for(filename, "input")
        with open(path, "wb") as f:
            f.write(content)
        url = output_url_for(filename, "input")
        register_internal_media_object(url, "input", kind, "ai-upload")
        item = {"url": url, "name": file.filename or filename, "kind": kind, "mime": content_type}
        if kind == "image":
            item.update({"width": image_width, "height": image_height, "orientation_normalized": orientation_normalized})
        uploaded.append(item)
    return {"files": uploaded}


@app.post("/api/canvas-bridges/film/import")
async def import_film_bridge_package(
    file: UploadFile = File(...),
    canvas_id: str = Form(""),
    selected_variant: str = Form(""),
    create_prompt_nodes: bool = Form(True),
):
    """导入 filmstoryboard 标准桥接包，并按 bridge/frame stable ID 增量更新目标画布。"""
    if not canvas_id.strip():
        raise HTTPException(status_code=400, detail="缺少目标画布。")
    load_canvas(canvas_id)
    filename = str(file.filename or "bridge.filmbridge.zip")
    suffix = Path(filename).suffix.lower()
    if suffix not in {".zip", ".filmbridge", ".shiyinbridge"}:
        raise HTTPException(status_code=400, detail="请选择 .filmbridge.zip、.filmbridge 或 .shiyinbridge 文件。")
    max_upload_bytes = 2 * 1024 * 1024 * 1024
    temp_fd, temp_name = tempfile.mkstemp(prefix="film_bridge_", suffix=suffix)
    os.close(temp_fd)
    extraction_root = tempfile.mkdtemp(prefix="film_bridge_extract_")
    package = None
    try:
        total = 0
        with open(temp_name, "wb") as output:
            while True:
                chunk = await file.read(1024 * 1024)
                if not chunk:
                    break
                total += len(chunk)
                if total > max_upload_bytes:
                    raise HTTPException(status_code=413, detail="桥接包不能超过 2GB。")
                output.write(chunk)
        if total <= 0:
            raise HTTPException(status_code=400, detail="桥接包为空。")
        try:
            package = await asyncio.to_thread(
                read_bridge_package,
                temp_name,
                extraction_root,
                max_total_bytes=max_upload_bytes,
            )
            frame_records = await asyncio.to_thread(
                materialize_bridge_frames,
                package,
                os.fspath(OUTPUT_INPUT_DIR),
                canvas_id,
                selected_variant=selected_variant,
            )
        except BridgePackageError as exc:
            raise HTTPException(status_code=400, detail=f"桥接包校验失败：{exc}") from exc
        frames = []
        for index, frame in enumerate(frame_records):
            local_path = frame.get("local_path") or ""
            url = media_url_from_path(local_path)
            if not url:
                raise HTTPException(status_code=500, detail="无法为桥接图片生成访问地址。")
            register_internal_media_object(url, "input", "image", "film-bridge")
            safe_frame = {key: value for key, value in frame.items() if key != "local_path"}
            safe_frame.update({
                "url": url,
                "name": frame.get("source_name") or f"film_frame_{index + 1:04d}{Path(local_path).suffix.lower() or '.png'}",
            })
            frames.append(safe_frame)
        manifest = package.manifest
        try:
            sync_result = sync_film_bridge_canvas(
                load_canvas(canvas_id),
                package.manifest,
                frames,
                create_prompt_nodes=bool(create_prompt_nodes),
            )
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=f"桥接增量同步失败：{exc}") from exc
        save_canvas(sync_result["canvas"])
        return {
            "bridge_id": manifest.get("bridge_id"),
            "direction": manifest.get("direction"),
            "source": manifest.get("source") or {},
            "canvas": manifest.get("canvas") or {},
            "storyboard": manifest.get("storyboard") or {},
            "frames": frames,
            "shots": manifest.get("shots") or [],
            "create_prompt_nodes": bool(create_prompt_nodes),
            "selected_variant": frames[0].get("variant") if frames else selected_variant or "original",
            "canvas_id": canvas_id,
            "group_id": sync_result["group"].get("id") or "",
            "frame_count": len(sync_result["image_nodes"]),
            "prompt_count": len(sync_result["prompt_nodes"]),
            "sync_mode": sync_result["sync_mode"],
            "sync_stats": sync_result["stats"],
        }
    finally:
        if package is not None:
            package.cleanup()
        shutil.rmtree(extraction_root, ignore_errors=True)
        Path(temp_name).unlink(missing_ok=True)


@app.post("/api/canvas-bridges/film/export")
async def export_film_bridge_package(
    canvas_id: str = Form(""),
    group_id: str = Form(""),
    selected_variant: str = Form(""),
    include_derived: bool = Form(True),
):
    """把当前 GROUP 及其衍生变体打包为 filmstoryboard 可导入的标准包。"""
    canvas = load_canvas(canvas_id)
    group = next((node for node in canvas.get("nodes", []) if node.get("id") == group_id and node.get("type") == "group"), None)
    if not group:
        raise HTTPException(status_code=404, detail="目标 GROUP 不存在。")
    try:
        manifest, files = await asyncio.to_thread(
            build_shiyin_bridge_payload,
            canvas=canvas,
            group=group,
            nodes=canvas.get("nodes") or [],
            local_path_for_url=output_file_from_url,
            selected_variant=selected_variant,
            include_derived=include_derived,
        )
        timestamp = time.strftime("%Y%m%d_%H%M%S", time.localtime())
        filename = f"shiyin_{canvas_id[:10]}_{group_id[:10]}_{timestamp}.filmbridge.zip"
        destination = output_path_for(filename, "output")
        result = await asyncio.to_thread(write_bridge_package, manifest, files, destination)
    except BridgePackageError as exc:
        raise HTTPException(status_code=400, detail=f"无法导出桥接包：{exc}") from exc
    url = output_url_for(filename, "output")
    register_internal_media_object(url, "output", "file", "film-bridge-export")
    return {
        "url": url,
        "filename": filename,
        "size": result.get("size") or 0,
        "file_count": result.get("file_count") or 0,
        "bridge_id": manifest.get("bridge_id"),
        "selected_variant": manifest.get("storyboard", {}).get("selected_variant"),
        "variants": manifest.get("storyboard", {}).get("variants") or [],
    }


def require_film_bridge_loopback(request: Request) -> None:
    if not is_loopback_address(request_remote_address(request)):
        raise HTTPException(status_code=403, detail="filmstoryboard 自动桥接仅允许本机访问。")


@app.get("/api/canvas-bridges/film/capabilities")
async def film_bridge_capabilities(request: Request):
    global ACTIVE_CANVAS_ID
    require_film_bridge_loopback(request)
    active_id = str(ACTIVE_CANVAS_ID or ACTIVE_CANVAS_BY_ACCOUNT.get(current_account_id()) or "").strip()
